<script setup lang="ts">
import { onMounted,ref } from 'vue';import { request } from '../api/client';import MailSettings from './MailSettings.vue';
const status=ref<{wecom:boolean;zentao:boolean}|null>(null),error=ref(''),activeTab=ref('providers');
onMounted(async()=>{try{const [wecom,zentao]=await Promise.all([request('/auth/wecom/status'),request('/auth/zentao/status')]);status.value={wecom:wecom.enabled,zentao:zentao.enabled}}catch(e){error.value=(e as Error).message}});
</script>
<template><div class="primary-page settings-page"><div class="primary-page-heading"><div><h1>认证配置</h1><p>查看登录方式的启用状态，配置安全验证邮件。</p></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-tabs v-model="activeTab" class="settings-tabs"><el-tab-pane label="登录方式" name="providers"><div class="primary-page-scroll" tabindex="0" aria-label="登录方式配置"><section class="panel"><div class="section-title"><h2>登录方式</h2><span>外部认证凭据由服务端安全配置</span></div><div class="provider-row"><div><h3>账号密码</h3><p>统一认证账号，由平台管理员创建</p></div><el-tag type="success" effect="plain">已启用</el-tag></div><div class="provider-row"><div><h3>企业微信</h3><p>员工在企业微信官方登录页面扫码</p></div><el-tag :type="status?.wecom?'success':'info'" effect="plain">{{status?status.wecom?'已启用':'未配置':'读取中'}}</el-tag></div><div class="provider-row"><div><h3>禅道账号</h3><p>通过已核对的禅道身份登录统一认证</p></div><el-tag :type="status?.zentao?'success':'info'" effect="plain">{{status?status.zentao?'已启用':'未配置':'读取中'}}</el-tag></div></section></div></el-tab-pane><el-tab-pane label="邮件设置" name="mail"><MailSettings/></el-tab-pane></el-tabs></div></template>
